  float signalFog(vec3 worldPos, vec3 camPos) {
    float d = length(worldPos - camPos);
    return 1.0 - exp(-(uFogDensity * uFogDensity) * (d * d));
  }
  vec3 applySignalFog(vec3 color, vec3 worldPos, vec3 camPos) {
